const app=document.getElementById('app');
const state={view:'capture',mode:'video',mic:true,camera:false,quality:'1080p · 30 fps',source:null,captured:false,audio:false,frame:true,title:'React in five minutes',background:'#69594a',padding:32,aspect:'16:9',position:'right',paused:false,seconds:0,playing:false,format:'MP4',filter:'all',exported:false};
let ticker=null,exportTimer=null,countTimer=null,toastTimer=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;
function scene(sample=false){return `<div class="scene ${state.aspect==='9:16'?'portrait':state.aspect==='1:1'?'square':''}" style="--back:${state.background};--padding:${sample?22:state.padding}px"><div class="screen-window"><div class="window-top" ${state.frame?'':'hidden'}><span class="dots"><i></i><i></i><i></i></span><span class="window-title">${esc(state.title)}</span></div><div class="code-body"><div class="line-numbers">1<br>2<br>3<br>4<br>5<br>6<br>7</div><div class="code-lines"><span class="code-comment">// Your next great tutorial.</span><br><span class="violet">export default function</span> App() {<br>&nbsp; <span class="violet">return</span> (<br>&nbsp;&nbsp; &lt;<span class="green">h1</span>&gt;Hello, creators.&lt;/<span class="green">h1</span>&gt;<br>&nbsp; );<br>}<br><span class="code-comment">// Build. Explain. Share.</span></div></div></div>${state.camera?`<div class="camera-bubble ${state.position==='left'?'left':''}">You</div>`:''}</div>`}
function steps(){const active=state.view==='style'?2:state.view==='export'?3:1;return `<nav class="steps" aria-label="Creation steps">${['Capture','Style','Export'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<button class="step ${active===i+1?'active':''}" ${active===i+1?'aria-current="step"':''} data-go="${s.toLowerCase()}" ${i>0&&!state.captured?'disabled':''}><b>${i+1}</b>${s}</button>`).join('')}</nav>`}
function toggle(key,label){return `<button class="switch" role="switch" aria-label="${label}" aria-checked="${state[key]}" data-toggle="${key}"></button>`}
function footer(){return `<div class="prototype-footer"><span>Design preview · recording, permissions and export are simulated.</span><button class="quiet" id="reset">Reset prototype ↺</button></div>`}
function render(){let content='';if(state.view!=='library')content+=steps();
if(state.view==='capture')content+=`<div class="capture-layout"><section class="capture-form"><div class="intro"><span class="eyebrow">YOUR IDEAS, BEAUTIFULLY CAPTURED</span><h1>What are you<br>creating today?</h1><p class="muted">A clear explanation starts with a great capture.</p></div><div class="mode-options"><button class="mode" data-mode="video" aria-pressed="${state.mode==='video'}"><span class="mode-symbol">▣</span><span><strong>Screen video</strong><small>Tutorials, demos, walkthroughs</small></span></button><button class="mode" data-mode="image" aria-pressed="${state.mode==='image'}"><span class="mode-symbol">▧</span><span><strong>Screenshot</strong><small>One moment, perfectly framed</small></span></button></div>${state.error?`<div class="error" role="alert">Screen access wasn’t granted. Choose what to share again when you’re ready. Your settings are preserved.</div>`:''}${state.mode==='video'?`<div class="field-row"><div>Narration<small>Your voice, alongside your screen</small></div><div class="right-control"><span class="small-note">${state.mic?'Microphone on':'Off'}</span>${toggle('mic','Microphone')}</div></div>${state.mic?'<div class="field-row"><label for="microphone">Microphone</label><div class="right-control"><span class="meter" aria-label="Sample audio level"></span><select id="microphone"><option>Default microphone</option><option>USB microphone (sample)</option></select></div></div>':''}<div class="field-row"><div>Show your face<small>A small webcam overlay</small></div><div class="right-control"><span class="small-note">${state.camera?'Camera on':'Camera off'}</span>${toggle('camera','Camera')}</div></div><div class="field-row"><label for="quality">Quality target<small>Actual capture depends on your source</small></label><select id="quality">${['1080p · 30 fps','1080p · 60 fps','Source resolution · 30 fps'].map(q=>`<option ${state.quality===q?'selected':''}>${q}</option>`).join('')}</select></div>`:'<div class="field-row"><div>Image quality<small>Capture first, crop and style afterward</small></div><span class="small-note">Source resolution · PNG</span></div>'}${state.source?`<div class="field-row"><div>Selected source<small>${esc(state.source)} · simulated</small></div><button class="quiet" id="choose">Change ↗</button></div>${state.mode==='video'?`<div class="field-row"><span>Source audio</span><span class="small-note">${state.audio?'Included in demo':'Not shared'}</span></div>`:''}<button class="${state.mode==='video'?'danger':'primary'} full" id="begin">${state.mode==='video'?'Start recording':'Capture screenshot'} <span>→</span></button><p class="hint">${state.mode==='video'?'3-second countdown · simulated capture':'Opens the screenshot styling workspace'}</p>`:`<button class="primary full" id="choose">Choose what to share <span>→</span></button><p class="hint">Choose your source, check your inputs, then capture.</p>`}</section><aside class="preview-aside"><div class="sample-label"><span>A LITTLE PREVIEW</span><span>${state.mode==='video'?'VIDEO':'SCREENSHOT'}</span></div>${scene(true)}<p class="sample-caption">Your content. A little more polished.<br>Add the finishing touches in Style.</p><div class="aside-rule"></div><span class="status-chip"><i></i> Designed for local downloads</span><p class="small-note" style="margin-top:12px">No upload needed for the planned recording flow.</p></aside></div>`;
if(state.view==='countdown')content+=`<section class="recording-layout"><h1 style="text-align:center">Get ready.</h1><p class="muted" style="text-align:center">Recording begins after the countdown.</p><div id="count" class="countdown">3</div><div class="recording-actions"><button class="secondary" data-go="capture">Cancel countdown</button></div></section>`;
if(state.view==='recording')content+=`<section class="recording-layout"><div class="record-status">${state.paused?'Ⅱ PAUSED':'● RECORDING DEMO'}</div><div class="timer" id="timer">${clock(state.seconds)}</div>${scene()}<p class="hint">Simulated capture · no screen, camera or microphone is being accessed.</p><div class="recording-actions"><button class="secondary" id="pause">${state.paused?'Resume recording':'Pause recording'}</button><button class="danger" id="finish">Finish recording →</button></div><p class="hint">${state.mic?'Microphone on':'Microphone off'} · ${state.audio?'Source audio included':'No source audio'}</p></section>`;
if(state.view==='style')content+=`<div class="toolbar"><div><span class="eyebrow">THE FINISHING TOUCHES</span><h1>Make it yours.</h1><p class="muted">${state.mode==='image'?'A screenshot':'A recording'} that looks as thoughtful as your work.</p></div><button class="primary" data-go="export">Continue to export →</button></div><div class="style-layout"><section><div class="preview-workspace"><div id="live-preview">${scene()}</div>${state.mode==='video'?`<div class="playback"><button id="play" aria-label="${state.playing?'Pause':'Play'} sample preview">${state.playing?'Ⅱ':'▶'}</button><span id="play-time">00:00 / ${clock(Math.max(state.seconds,18))}</span><span>${state.aspect} · Fit</span></div><input class="scrub" id="scrub" type="range" min="0" max="${Math.max(state.seconds,18)}" value="0" aria-label="Preview position">`:`<div class="playback"><span>Screenshot preview</span><span>${state.aspect} · Fit</span></div>`}</div><p class="hint">Sample content · the frame and background are part of the export design.</p>${state.mode==='image'?`<div class="field-row"><div>Crop preview<small>Adjusts sample framing only</small></div><label><input id="crop" type="range" min="100" max="140" value="100" aria-label="Screenshot crop zoom"></label></div>`:''}</section><aside class="inspector"><h2>Presentation</h2><label class="control"><span>Canvas size</span></label><div class="aspect-buttons">${['16:9','9:16','1:1'].map(a=>`<button data-aspect="${a}" aria-pressed="${state.aspect===a}">${a}</button>`).join('')}</div><div class="field-row"><div>Mac-style frame<small>Red, yellow and green dots</small></div>${toggle('frame','Mac-style window frame')}</div><label class="control"><span>Window title</span><input type="text" id="title" value="${esc(state.title)}" maxlength="70"></label><label class="control"><span>Background</span></label><div class="swatches">${[['#69594a','Warm stone'],['#3c4642','Forest'],['#404351','Slate'],['#493b45','Plum'],['#272624','Charcoal']].map(([c,n])=>`<button class="swatch" style="background:${c}" data-color="${c}" aria-label="${n}" aria-pressed="${state.background===c}"></button>`).join('')}</div><label class="control"><span>Padding <output id="padding-label">${state.padding} px</output></span><input type="range" id="padding" min="0" max="64" value="${state.padding}"></label>${state.mode==='video'?`<div class="field-row"><span>Webcam overlay</span>${toggle('camera','Webcam overlay')}</div>${state.camera?`<label class="control"><span>Webcam position</span><select id="position"><option value="right" ${state.position==='right'?'selected':''}>Bottom right</option><option value="left" ${state.position==='left'?'selected':''}>Bottom left</option></select></label>`:''}`:''}<p class="small-note" style="margin:18px 0 0">You can return to this step before exporting.</p></aside></div><div class="footer-actions"><button class="quiet" data-go="capture">← Back to capture</button><span class="small-note">Changes apply to this demo only</span></div>`;
if(state.view==='export')content+=`<div class="toolbar"><div><span class="eyebrow">READY FOR THE WORLD</span><h1>Your work, ready to go.</h1><p class="muted">Review the details, then save to your computer.</p></div></div><div class="export-layout"><section><div class="preview-workspace">${scene()}</div><p class="hint">${state.mode==='image'?'Screenshot':'Video'} · ${state.aspect} · ${state.frame?'Mac-style frame':'No window frame'}</p><button class="quiet" data-go="style">← Back to styling</button></section><section class="export-summary"><h2>Export ${state.mode==='image'?'screenshot':'video'}</h2><label for="filename">File name</label><input id="filename" type="text" value="${esc(state.title)}" maxlength="100"><div class="field-row"><label for="format">Format</label>${state.mode==='image'?'<span>PNG</span>':`<select id="format"><option ${state.format==='MP4'?'selected':''}>MP4</option><option ${state.format==='WebM'?'selected':''}>WebM</option></select>`}</div><div class="field-row"><span>Output target</span><span class="small-note">${state.aspect==='9:16'?'1080 × 1920':state.aspect==='1:1'?'1080 × 1080':'1920 × 1080'}</span></div>${state.mode==='video'?`<div class="field-row"><span>Frame rate target</span><span>${state.quality.includes('60')?'60':'30'} fps</span></div>`:''}<div class="field-row"><span>Save location</span><span class="small-note">Choose when saving</span></div><div class="small-note" style="margin-top:18px">${state.mode==='video'?'MP4 availability will be checked in the working app. WebM will be offered when MP4 is unsupported.':'PNG preserves the screenshot detail without video compression.'}</div><button class="primary full" id="export-demo">Preview save flow ↓</button><div id="export-progress" aria-live="polite"></div><p class="hint">Prototype only — no media file is downloaded.</p><details ${state.mode==='image'?'hidden':''}><summary>Preview unavailable MP4</summary><button class="quiet" id="fallback">Simulate MP4 fallback</button></details></section></div>`;
if(state.view==='library')content+=`<div class="library-head"><div><span class="eyebrow">YOUR CREATIVE SPACE</span><h1>My captures</h1><p class="muted">Good ideas deserve another look.</p></div><button class="primary" id="new">New capture +</button></div><div class="library-tabs">${[['all','All captures'],['video','Videos'],['image','Screenshots']].map(([v,n])=>`<button data-filter="${v}" class="${state.filter===v?'active':''}">${n}</button>`).join('')}</div><div class="library-grid">${[['React in five minutes','video','Video · 00:18'],['API response example','image','Screenshot · PNG'],['Deploy your first app','video','Video · 02:34']].filter(x=>state.filter==='all'||x[1]===state.filter).map(([title,mode,desc])=>`<button class="capture-item" data-item="${esc(title)}" data-kind="${mode}">${scene(true)}<strong>${title}</strong><small>${desc} · Sample project</small></button>`).join('')}</div><p class="small-note" style="margin-top:30px">Sample library for design review. No recordings are stored by this prototype.</p>`;
app.innerHTML=content+footer();bind();}
function updatePreview(){const preview=document.getElementById('live-preview');if(preview)preview.innerHTML=scene()}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4000)}
function go(view){clearInterval(ticker);clearInterval(countTimer);clearInterval(exportTimer);state.playing=false;state.view=view;render();window.scrollTo({top:0,behavior:'instant'})}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;state.source=null;state.captured=false;state.error=false;render()});document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{state[b.dataset.toggle]=!state[b.dataset.toggle];render()});document.querySelectorAll('[data-aspect]').forEach(b=>b.onclick=()=>{state.aspect=b.dataset.aspect;render()});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.background=b.dataset.color;document.querySelectorAll('[data-color]').forEach(x=>x.setAttribute('aria-pressed',x===b));updatePreview()});
const on=(id,event,fn)=>{const el=document.getElementById(id);if(el)el.addEventListener(event,fn)};
on('choose','click',()=>document.getElementById('source-dialog').showModal());on('quality','change',e=>state.quality=e.target.value);on('title','input',e=>{state.title=e.target.value;updatePreview()});on('padding','input',e=>{state.padding=+e.target.value;document.getElementById('padding-label').textContent=state.padding+' px';updatePreview()});on('position','change',e=>{state.position=e.target.value;updatePreview()});on('crop','input',e=>{const win=document.querySelector('#live-preview .screen-window');win.style.transform=`scale(${e.target.value/100})`});on('filename','input',e=>state.title=e.target.value);on('format','change',e=>state.format=e.target.value);on('fallback','click',()=>{state.format='WebM';render();toast('MP4 unavailable in this simulated case. WebM selected instead.')});
on('begin','click',()=>{if(state.mode==='image'){state.captured=true;go('style');return}state.seconds=0;state.paused=false;go('countdown');let n=3;countTimer=setInterval(()=>{n--;if(n===0){go('recording');startTimer()}else document.getElementById('count').textContent=n},1000)});on('pause','click',()=>{state.paused=!state.paused;render()});on('finish','click',()=>{state.captured=true;go('style')});on('play','click',()=>{state.playing=!state.playing;document.getElementById('play').textContent=state.playing?'Ⅱ':'▶';document.getElementById('play').setAttribute('aria-label',state.playing?'Pause sample preview':'Play sample preview');clearInterval(ticker);if(state.playing)ticker=setInterval(()=>{const scrub=document.getElementById('scrub');if(!scrub)return;let v=+scrub.value+1;if(v>+scrub.max)v=0;scrub.value=v;document.getElementById('play-time').textContent=clock(v)+' / '+clock(+scrub.max)},1000)});on('scrub','input',e=>document.getElementById('play-time').textContent=clock(+e.target.value)+' / '+clock(+e.target.max));on('export-demo','click',()=>{const button=document.getElementById('export-demo');button.disabled=true;let p=0;const progress=document.getElementById('export-progress');progress.innerHTML='<div class="progress-track"><div class="progress-fill" style="width:0%"></div></div><span class="small-note">Preparing sample export…</span>';exportTimer=setInterval(()=>{p+=20;progress.querySelector('.progress-fill').style.width=p+'%';if(p>=100){clearInterval(exportTimer);state.exported=true;progress.innerHTML='<div class="success">✓ Save flow complete — demonstration only.</div><p class="small-note">In the working app, choose Desktop in the supported Save as dialog, or use your browser’s download location.</p>';button.disabled=false;button.textContent='Preview again';}},300)});on('new','click',()=>{state.source=null;state.captured=false;state.error=false;go('capture')});on('reset','click',()=>{clearInterval(ticker);clearInterval(countTimer);clearInterval(exportTimer);Object.assign(state,{view:'capture',mode:'video',source:null,captured:false,error:false,mic:true,camera:false,quality:'1080p · 30 fps',frame:true,title:'React in five minutes',background:'#69594a',padding:32,aspect:'16:9',position:'right',format:'MP4',seconds:0,paused:false});render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{state.title=b.dataset.item;state.mode=b.dataset.kind;state.source='Sample project';state.captured=true;state.seconds=18;go('style')});}
function startTimer(){ticker=setInterval(()=>{if(!state.paused){state.seconds++;const el=document.getElementById('timer');if(el)el.textContent=clock(state.seconds)}},1000)}
let sourceType='Browser tab';document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{sourceType=b.dataset.source;document.querySelectorAll('[data-source]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('source-name').textContent=sourceType==='Entire screen'?'Display 1 — Entire screen':'React tutorial — '+sourceType});document.getElementById('source-card').onclick=()=>toast('Sample source selected');document.getElementById('confirm-source').onclick=()=>{state.source=sourceType;state.audio=document.getElementById('share-audio').checked;state.error=false;document.getElementById('source-dialog').close();render()};document.getElementById('deny-source').onclick=()=>{state.source=null;state.error=true;document.getElementById('source-dialog').close();render()};render();


